def norm(raw,cal):
 import math
 return [100/(1+math.exp(-2.197224577*(x-cal['center'][k])/cal['spread'][k])) for k,x in enumerate(raw)]
def gen(sc):
 import math
 return .5*min(sc)+.5*math.exp(sum(math.log(max(.01,x)) for x in sc)/4)
